function subsequencePairCount(nums) {
  const MOD = 1_000_000_007;
  const maxValue = Math.max(...nums);
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  // dp[g1][g2]: ways to place the numbers seen so far so that seq1 has GCD g1 and seq2 has GCD g2 (0 = empty).
  let dp = Array.from({ length: maxValue + 1 }, () => new Int32Array(maxValue + 1));
  dp[0][0] = 1;
  // The GCDs a side can have so far; every other row and column of dp is zero.
  const reachable = [0];
  const isReachable = new Array(maxValue + 1).fill(false);
  isReachable[0] = true;
  for (const num of nums) {
    const joined = new Array(maxValue + 1);
    for (const g of reachable) {
      joined[g] = gcd(g, num);
    }
    const next = dp.map(row => row.slice());
    for (const g1 of reachable) {
      const row = dp[g1];
      const joinFirst = next[joined[g1]];
      const joinSecond = next[g1];
      for (const g2 of reachable) {
        const ways = row[g2];
        if (ways === 0) {
          continue;
        }
        joinFirst[g2] = (joinFirst[g2] + ways) % MOD;
        joinSecond[joined[g2]] = (joinSecond[joined[g2]] + ways) % MOD;
      }
    }
    dp = next;
    for (const g of reachable.slice()) {
      if (!isReachable[joined[g]]) {
        isReachable[joined[g]] = true;
        reachable.push(joined[g]);
      }
    }
  }
  let total = 0;
  for (let g = 1; g <= maxValue; g++) {
    total = (total + dp[g][g]) % MOD;
  }
  return total;
}

