function subsequencePairCount(nums) {
  // Try all 3^n ways to send each index to seq1, seq2 or neither.
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const n = nums.length;
  let count = 0;
  for (let code = 0; code < 3 ** n; code++) {
    let rest = code, first = 0, second = 0;
    for (let i = 0; i < n; i++) {
      const choice = rest % 3;
      rest = (rest - choice) / 3;
      if (choice === 1) first = gcd(first, nums[i]);
      if (choice === 2) second = gcd(second, nums[i]);
    }
    if (first > 0 && first === second) count++;
  }
  return count % 1000000007;
}

